const resposta = $('Extrair dados').first().json.texto.trim();
const nome = String(p.nome || '').trim().split(/\s+/)[0] || '';
const instrucao = p.tipo === 'orcamento_cabelo' ? 'Você é a assistente virtual da Caroline, do salão Studio Caroline Ferreira, conversando pelo WhatsApp com a cliente ' +
  (nome || '') + '. A cliente pediu o orçamento deste cabelo: "' + p.pergunta + '". A Caroline respondeu: "' + resposta + '". ' +
